-- Step 1: Create and select the database
DROP DATABASE IF EXISTS ev_charging_india;
CREATE DATABASE ev_charging_india;
USE ev_charging_india;

-- ============================================================
-- TABLE 1: users
-- ============================================================
CREATE TABLE users (
    user_id       INT PRIMARY KEY,
    full_name     VARCHAR(100)  NOT NULL,
    email         VARCHAR(150)  NOT NULL UNIQUE,
    phone         VARCHAR(15)   NOT NULL,
    city          VARCHAR(50)   NOT NULL,
    user_type     VARCHAR(50)   NOT NULL,   -- Commuter / Casual Driver / Long-Distance Traveler / Fleet Driver
    joined_date   DATE          NOT NULL
);

-- ============================================================
-- TABLE 2: vehicles
-- ============================================================
CREATE TABLE vehicles (
    vehicle_id          INT PRIMARY KEY,
    user_id             INT          NOT NULL,
    model               VARCHAR(100) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    battery_capacity_kwh DECIMAL(5,1) NOT NULL,
    vehicle_age_years   INT          NOT NULL,
    registration_number VARCHAR(20)  NOT NULL UNIQUE,
    is_active           TINYINT(1)   NOT NULL DEFAULT 1,
    FOREIGN KEY (user_id) REFERENCES users(user_id)
);

-- ============================================================
-- TABLE 3: charging_stations
-- ============================================================
CREATE TABLE charging_stations (
    station_id      INT PRIMARY KEY,
    station_name    VARCHAR(150) NOT NULL,
    city            VARCHAR(50)  NOT NULL,
    area            VARCHAR(100) NOT NULL,
    operator        VARCHAR(100) NOT NULL,
    charger_type    VARCHAR(50)  NOT NULL,   -- AC Slow / AC Fast / DC Fast / DC Rapid
    max_power_kw    DECIMAL(6,1) NOT NULL,
    price_per_kwh   DECIMAL(5,2) NOT NULL,   -- INR per kWh
    total_slots     INT          NOT NULL,
    is_operational  TINYINT(1)   NOT NULL DEFAULT 1,
    installed_date  DATE         NOT NULL
);

-- ============================================================
-- TABLE 4: charging_sessions
-- ============================================================
CREATE TABLE charging_sessions (
    session_id            INT PRIMARY KEY,
    user_id               INT           NOT NULL,
    vehicle_id            INT           NOT NULL,
    station_id            INT           NOT NULL,
    charging_start        DATETIME      NOT NULL,
    charging_end          DATETIME      NOT NULL,
    energy_consumed_kwh   DECIMAL(6,2)  NOT NULL,
    charging_duration_hrs DECIMAL(5,2)  NOT NULL,
    charging_rate_kw      DECIMAL(6,2)  NOT NULL,
    charging_cost_inr     DECIMAL(8,2)  NOT NULL,
    soc_start_pct         DECIMAL(5,2)  NOT NULL,   -- State of Charge at start
    soc_end_pct           DECIMAL(5,2)  NOT NULL,   -- State of Charge at end
    distance_driven_km    DECIMAL(7,2)  NOT NULL,   -- Distance driven before this session
    temperature_c         DECIMAL(4,1)  NOT NULL,
    time_of_day           VARCHAR(20)   NOT NULL,   -- Morning / Afternoon / Evening / Night
    day_of_week           VARCHAR(15)   NOT NULL,
    FOREIGN KEY (user_id)    REFERENCES users(user_id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id),
    FOREIGN KEY (station_id) REFERENCES charging_stations(station_id)
);

-- ============================================================
-- TABLE 5: payments
-- ============================================================
CREATE TABLE payments (
    payment_id      INT PRIMARY KEY,
    session_id      INT           NOT NULL,
    user_id         INT           NOT NULL,
    amount_inr      DECIMAL(8,2)  NOT NULL,
    payment_method  VARCHAR(50)   NOT NULL,   -- UPI / Credit Card / Debit Card / Wallet / Net Banking
    payment_status  VARCHAR(20)   NOT NULL,   -- Completed / Failed / Refunded
    paid_at         DATETIME      NOT NULL,
    FOREIGN KEY (session_id) REFERENCES charging_sessions(session_id),
    FOREIGN KEY (user_id)    REFERENCES users(user_id)
);

-- ============================================================
-- TABLE 6: station_reviews
-- ============================================================
CREATE TABLE station_reviews (
    review_id   INT PRIMARY KEY,
    session_id  INT          NOT NULL,
    user_id     INT          NOT NULL,
    station_id  INT          NOT NULL,
    rating      TINYINT      NOT NULL,   -- 1 to 5
    comment     VARCHAR(255),
    reviewed_at DATETIME     NOT NULL,
    FOREIGN KEY (session_id)  REFERENCES charging_sessions(session_id),
    FOREIGN KEY (user_id)     REFERENCES users(user_id),
    FOREIGN KEY (station_id)  REFERENCES charging_stations(station_id)
);

